-- Quant timestamps use UTC in DATETIME columns where the previous writer was known.
-- Production MySQL global/session time_zone was verified as SYSTEM / UTC+08:00.
-- Only fields exclusively generated by Java Asia/Shanghai or SQL NOW/CURRENT_TIMESTAMP
-- under that verified +08:00 clock are shifted. Exchange event facts and mixed-source
-- historical timestamps are intentionally not normalized by this script.
--
-- Run exactly once after V20261104_01__account_trade_cycle_projection.sql.
-- Tables added in later live-hardening deployments are updated conditionally so an
-- older schema does not fail halfway through this migration.

SET @quant_utc_sql = IF(
  EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='quant_account_snapshot'),
  'UPDATE quant_account_snapshot SET observed_at=DATE_SUB(observed_at, INTERVAL 8 HOUR)',
  'SELECT 1'
);
PREPARE quant_utc_stmt FROM @quant_utc_sql;
EXECUTE quant_utc_stmt;
DEALLOCATE PREPARE quant_utc_stmt;

